/*
 * Generates extension/page-main.js from the existing page-world sources.
 *
 * The generated file is registered as a MAIN-world content script at
 * document_start. The isolated content script posts the per-frame config;
 * these listeners install the legacy patches with a fake currentScript and
 * then delete the update globals, keeping only closure references.
 */
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const extension = path.join(root, "extension");
const injectSource = fs.readFileSync(path.join(extension, "inject.js"), "utf8");
const protectSource = fs.readFileSync(path.join(extension, "protect.js"), "utf8");
const personaSource = fs.readFileSync(path.join(extension, "persona.js"), "utf8");

function makeConfigurable(source, property, label) {
  const pattern = new RegExp(`(Object\\.defineProperty\\(window,\\s*"${property}",\\s*\\{[\\s\\S]*?configurable:\\s*)(?:false|!1)`);
  if (!pattern.test(source)) throw new Error(`${label} update descriptor not found`);
  return source.replace(pattern, "$1true");
}

function wrap(source, label, updateProperty, marker, configKey, restoreRTC) {
  const configurable = makeConfigurable(source, updateProperty, label);
  const rtcCapture = restoreRTC
    ? `    const __lcNativeRTC = window.RTCPeerConnection;\n    const __lcNativeWebkitRTC = window.webkitRTCPeerConnection;\n`
    : "";
  const rtcRestore = restoreRTC
    ? `\n    if (__lcNativeRTC) window.RTCPeerConnection = __lcNativeRTC;\n    if (__lcNativeWebkitRTC) window.webkitRTCPeerConnection = __lcNativeWebkitRTC;`
    : "";
  return `(function () {
  "use strict";
  let installed = false;
  let update = null;

  function install(__lcConfig) {
${rtcCapture}    const __lcFakeScript = {
      getAttribute: function () { return JSON.stringify(__lcConfig || {}); },
      parentNode: null
    };
    const __lcDocument = new Proxy(document, {
      get: function (target, property) {
        if (property === "currentScript") return __lcFakeScript;
        return Reflect.get(target, property, target);
      }
    });
    (function (document) {
${configurable}
    })(__lcDocument);
${rtcRestore}
    update = window.${updateProperty};
    try { delete window.${updateProperty}; } catch (error) {}
    try { delete window[Symbol.for("${marker}")]; } catch (error) {}
  }

  window.addEventListener("message", function (event) {
    if (event.source !== window || !event.data || event.data.__lc_config !== true) return;
    const config = event.data.${configKey};
    if (!installed) {
      installed = true;
      install(config);
    } else if (typeof update === "function") {
      update(config);
    }
  });
})();`;
}

const output = `/* Generated by tools/build-main.js; do not edit directly. */
${wrap(injectSource, "__lcPageMain", "__locacloak_update__", "__lc__", "core", true)}

${wrap(protectSource, "__lcProtectMain", "__locacloak_protect_update__", "__lc_protect__", "protect", false)}

${personaSource}
`;

fs.writeFileSync(path.join(extension, "page-main.js"), output);
console.log(`wrote ${path.join(extension, "page-main.js")} (${output.length} bytes)`);
